package cn.zhuatech.grc.controller; import cn.zhuatech.grc.common.ApiResponse; import cn.zhuatech.grc.dto.GrcDto.*; import cn.zhuatech.grc.service.GrcService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('GRC_MANAGER','QUALITY','ADMIN')") public class GovernanceAdminController {private final GrcService service;public GovernanceAdminController(GrcService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<AssessmentView>> orders(){return ApiResponse.ok(service.assessments());}}
